from collections import deque

def bfs(graph, start):
    q = deque([start])
    dist = {start: 0}
    while q:
        u = q.popleft()
        for v in graph[u]:
            if v not in dist:          # mark on ENQUEUE
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

